import os
import json
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def _as_dict(obj: Any) -> Any:
    if obj is None:
        return None
    if isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, list):
        return [_as_dict(x) for x in obj]
    if isinstance(obj, dict):
        return {k: _as_dict(v) for k, v in obj.items()}
    if hasattr(obj, "items"):
        try:
            return {k: _as_dict(v) for k, v in obj.items()}
        except Exception:
            pass
    if hasattr(obj, "__dict__"):
        return {k: _as_dict(v) for k, v in obj.__dict__.items() if not k.startswith("_")}
    return str(obj)


def _get_field(fields: Dict[str, Any], *names: str) -> Any:
    for name in names:
        if name in fields and fields[name] is not None:
            return fields[name]
    lowered = {k.lower(): v for k, v in fields.items()}
    for name in names:
        v = lowered.get(name.lower())
        if v is not None:
            return v
    return None


def _normalize_currency_amount(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, dict):
        for key in ("amount", "value", "content"):
            if key in value and value[key] is not None:
                return value[key]
    return getattr(value, "value", value)


def extract_invoice_fields(file_path: str) -> Dict[str, Any]:
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")
    if not endpoint or not key:
        raise ValueError(
            "Missing Azure Document Intelligence configuration. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id="prebuilt-invoice",
            analyze_request=f,
            content_type="application/octet-stream",
        )
        result = poller.result()

    docs = getattr(result, "documents", None) or []
    if not docs:
        return {"vendor": None, "date": None, "total": None, "line_items": []}

    doc = docs[0]
    fields = getattr(doc, "fields", {}) or {}

    vendor_field = _get_field(fields, "VendorName", "Vendor", "SupplierName", "MerchantName")
    date_field = _get_field(fields, "InvoiceDate", "Date")
    total_field = _get_field(fields, "InvoiceTotal", "Total")
    line_items_field = _get_field(fields, "Items", "LineItems", "InvoiceItems")

    vendor = None
    if vendor_field is not None:
        vendor = getattr(vendor_field, "content", None) or getattr(vendor_field, "value", None) or str(vendor_field)

    date = None
    if date_field is not None:
        date = (
            getattr(date_field, "content", None)
            or getattr(date_field, "value", None)
            or getattr(date_field, "value_date", None)
            or str(date_field)
        )

    total = None
    if total_field is not None:
        total = _normalize_currency_amount(
            getattr(total_field, "value_currency", None)
            or getattr(total_field, "value", None)
            or total_field
        )

    line_items: List[Dict[str, Any]] = []
    if line_items_field is not None:
        items = getattr(line_items_field, "value_array", None) or getattr(line_items_field, "value", None) or []
        for item in items:
            item_fields = getattr(item, "value_object", None) or getattr(item, "fields", None) or {}
            if hasattr(item_fields, "items"):
                item_fields = dict(item_fields.items())
            else:
                item_fields = _as_dict(item_fields) or {}

            description_field = _get_field(item_fields, "Description", "ProductCode", "Name")
            quantity_field = _get_field(item_fields, "Quantity")
            unit_price_field = _get_field(item_fields, "UnitPrice", "UnitCost")
            amount_field = _get_field(item_fields, "Amount", "TotalPrice", "LineTotal")

            line_items.append(
                {
                    "description": (
                        getattr(description_field, "content", None)
                        or getattr(description_field, "value", None)
                        or str(description_field)
                        if description_field is not None
                        else None
                    ),
                    "quantity": (
                        getattr(quantity_field, "value", None)
                        if quantity_field is not None
                        else None
                    ),
                    "unit_price": _normalize_currency_amount(
                        getattr(unit_price_field, "value_currency", None)
                        or getattr(unit_price_field, "value", None)
                        or unit_price_field
                    ),
                    "amount": _normalize_currency_amount(
                        getattr(amount_field, "value_currency", None)
                        or getattr(amount_field, "value", None)
                        or amount_field
                    ),
                }
            )

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
    }
